103					ReturnType: &schema.ReturnTypeSpec{
104						ObjectTypeSpec: &schema.ObjectTypeSpec{
105							Type:       "object",
106							Properties: resourceProperties,
107							Required:   resourceRequired,
108						},
109					},
110				},
111			},
112		}
113	
114		jsonBytes, err := json.Marshal(pkg)
115		return plugin.GetSchemaResponse{Schema: jsonBytes}, err
